@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@300;400;500;600&display=swap');

*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --red: #FF0000;
  --red-hover: #cc0000;
  --red-dark: #990000;
  --bg: #141414;
  --bg-light: #1a1a1a;
  --bg-card: #1e1e1e;
  --bg-card-hover: #252525;
  --white: #FFFFFF;
  --gray: #b0b0b0;
  --gray-light: #d0d0d0;
  --gray-dark: #666;
  --font-heading: 'Oswald', sans-serif;
  --font-body: 'Inter', sans-serif;
  --transition: 0.3s ease;
  --max-width: 1200px;
}

html { scroll-behavior: smooth; font-size: 16px; }

body {
  background: var(--bg);
  color: var(--white);
  font-family: var(--font-body);
  line-height: 1.6;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
ul { list-style: none; }
img { max-width: 100%; display: block; }
button { cursor: pointer; border: none; font-family: var(--font-body); }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* TOP BAR */
.top-bar {
  background: var(--red);
  text-align: center;
  padding: 10px 16px;
  font-family: var(--font-heading);
  font-size: 0.85rem;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  font-weight: 500;
}
.top-bar a {
  color: var(--white);
  text-decoration: underline;
  margin-left: 10px;
  font-weight: 600;
}

/* NAVBAR */
.navbar {
  background: rgba(20, 20, 20, 0.95);
  backdrop-filter: blur(12px);
  position: sticky;
  top: 0;
  z-index: 1000;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}
.navbar .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 0;
  padding-bottom: 0;
  height: 70px;
}
.nav-logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--white);
}
.nav-logo span { color: var(--red); }

.nav-links {
  display: flex;
  gap: 28px;
  align-items: center;
}
.nav-links a {
  font-family: var(--font-heading);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--gray-light);
  transition: color var(--transition);
  position: relative;
  padding: 4px 0;
}
.nav-links a::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--red);
  transition: width var(--transition);
}
.nav-links a:hover { color: var(--white); }
.nav-links a:hover::after { width: 100%; }
.nav-links a.active { color: var(--red); }

.nav-utility {
  display: flex;
  gap: 16px;
  align-items: center;
}
.nav-utility a {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--gray);
  transition: color var(--transition);
}
.nav-utility a:hover { color: var(--white); }

.btn-book {
  background: var(--red);
  color: var(--white);
  padding: 10px 24px;
  font-family: var(--font-heading);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  font-weight: 600;
  border-radius: 0;
  transition: background var(--transition), transform var(--transition);
  display: inline-block;
}
.btn-book:hover { background: var(--red-hover); transform: translateY(-1px); }

/* HAMBURGER */
.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  padding: 8px;
}
.hamburger span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--white);
  transition: var(--transition);
}

/* HERO */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: linear-gradient(135deg, rgba(255, 0, 0, 0.15) 0%, rgba(20, 20, 20, 1) 50%, rgba(20, 20, 20, 1) 100%);
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background: radial-gradient(ellipse at center top, rgba(255, 0, 0, 0.08) 0%, transparent 70%);
  pointer-events: none;
}
.hero-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
  padding: 40px 24px;
}
.hero h1 {
  font-family: var(--font-heading);
  font-size: clamp(2.5rem, 6vw, 5rem);
  text-transform: uppercase;
  letter-spacing: 4px;
  line-height: 1.1;
  font-weight: 700;
  margin-bottom: 20px;
}
.hero h1 span { color: var(--red); }
.hero p {
  font-size: 1.1rem;
  color: var(--gray-light);
  margin-bottom: 36px;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
  line-height: 1.7;
}
.hero-btns {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}
.btn-primary {
  background: var(--red);
  color: var(--white);
  padding: 16px 48px;
  font-family: var(--font-heading);
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 3px;
  font-weight: 600;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
  display: inline-block;
}
.btn-primary:hover {
  background: var(--red-hover);
  transform: translateY(-2px);
  box-shadow: 0 8px 30px rgba(255, 0, 0, 0.3);
}
.btn-secondary {
  background: transparent;
  color: var(--white);
  padding: 16px 48px;
  font-family: var(--font-heading);
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 3px;
  font-weight: 600;
  border: 2px solid var(--white);
  transition: all var(--transition);
  display: inline-block;
}
.btn-secondary:hover {
  background: var(--white);
  color: var(--bg);
  transform: translateY(-2px);
}

/* SECTIONS */
section { padding: 100px 0; }
.section-heading {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3.5rem);
  text-transform: uppercase;
  letter-spacing: 3px;
  text-align: center;
  margin-bottom: 20px;
  font-weight: 700;
  line-height: 1.15;
}
.section-heading span { color: var(--red); }
.section-subtext {
  text-align: center;
  color: var(--gray);
  max-width: 700px;
  margin: 0 auto 60px;
  font-size: 1.05rem;
  line-height: 1.7;
}

/* COMMUNITY PROMO */
.community {
  background: var(--bg-light);
  text-align: center;
}

/* TWO WAYS */
.two-ways-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 30px;
  margin-top: 50px;
}
.way-card {
  background: var(--bg-card);
  border: 1px solid rgba(255, 255, 255, 0.06);
  padding: 50px 40px;
  text-align: center;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}
.way-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: var(--red);
  transform: scaleX(0);
  transition: transform var(--transition);
}
.way-card:hover::before { transform: scaleX(1); }
.way-card:hover { border-color: rgba(255, 0, 0, 0.2); transform: translateY(-4px); }
.way-card h3 {
  font-family: var(--font-heading);
  font-size: 1.8rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 16px;
  color: var(--red);
}
.way-card p {
  color: var(--gray);
  line-height: 1.7;
  font-size: 0.95rem;
}

/* STUDIO EXPERIENCE */
.studio {
  background: linear-gradient(to bottom, var(--bg), var(--bg-light));
  text-align: center;
}
.studio-cta {
  margin-top: 50px;
  font-family: var(--font-heading);
  font-size: 1.1rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--gray-light);
  line-height: 1.6;
}

/* FREE TRIAL */
.free-trial {
  background: var(--red);
  text-align: center;
  padding: 80px 0;
  position: relative;
  overflow: hidden;
}
.free-trial::before {
  content: '';
  position: absolute;
  top: -50%; left: -50%;
  width: 200%;
  height: 200%;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.05) 0%, transparent 60%);
  pointer-events: none;
}
.free-trial h2 {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3.5rem);
  text-transform: uppercase;
  letter-spacing: 4px;
  margin-bottom: 30px;
  position: relative;
}
.free-trial .btn-primary {
  background: var(--white);
  color: var(--red);
  position: relative;
}
.free-trial .btn-primary:hover {
  background: var(--bg);
  color: var(--white);
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.4);
}

/* CAROUSEL */
.carousel-section { background: var(--bg-light); overflow: hidden; }
.carousel-wrapper {
  position: relative;
  max-width: 1000px;
  margin: 0 auto;
  overflow: hidden;
}
.carousel-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}
.carousel-slide {
  min-width: 100%;
  aspect-ratio: 16/9;
  background: var(--bg-card);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.carousel-slide-inner {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 1.5rem;
  text-transform: uppercase;
  letter-spacing: 3px;
  color: var(--gray-dark);
  background: linear-gradient(135deg, var(--bg-card) 0%, #222 100%);
}
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  background: rgba(255, 0, 0, 0.85);
  color: var(--white);
  width: 50px;
  height: 50px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.4rem;
  z-index: 10;
  transition: all var(--transition);
}
.carousel-btn:hover { background: var(--red); transform: translateY(-50%) scale(1.05); }
.carousel-btn.prev { left: 16px; }
.carousel-btn.next { right: 16px; }
.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-top: 24px;
}
.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--gray-dark);
  border: none;
  transition: all var(--transition);
}
.carousel-dot.active { background: var(--red); transform: scale(1.3); }

/* NEWSLETTER */
.newsletter {
  background: var(--bg);
  text-align: center;
  padding: 80px 0;
  border-top: 1px solid rgba(255, 255, 255, 0.04);
}
.newsletter-form {
  display: flex;
  gap: 0;
  max-width: 500px;
  margin: 0 auto;
}
.newsletter-form input[type="email"] {
  flex: 1;
  padding: 16px 20px;
  background: var(--bg-card);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: var(--white);
  font-family: var(--font-body);
  font-size: 0.95rem;
  outline: none;
  transition: border-color var(--transition);
}
.newsletter-form input[type="email"]::placeholder { color: var(--gray-dark); }
.newsletter-form input[type="email"]:focus { border-color: var(--red); }
.newsletter-form input[type="email"].error { border-color: #ff4444; }
.newsletter-form input[type="email"].success { border-color: #44bb44; }
.newsletter-form button {
  background: var(--red);
  color: var(--white);
  padding: 16px 32px;
  font-family: var(--font-heading);
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  font-weight: 600;
  transition: background var(--transition);
  white-space: nowrap;
}
.newsletter-form button:hover { background: var(--red-hover); }
.newsletter-msg {
  margin-top: 12px;
  font-size: 0.85rem;
  min-height: 20px;
}
.newsletter-msg.error { color: #ff4444; }
.newsletter-msg.success { color: #44bb44; }

/* FOOTER */
.footer {
  background: #0a0a0a;
  padding: 80px 0 40px;
  border-top: 1px solid rgba(255, 255, 255, 0.04);
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 50px;
}
.footer-col h4 {
  font-family: var(--font-heading);
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 20px;
  color: var(--red);
}
.footer-col a {
  display: block;
  color: var(--gray);
  font-size: 0.9rem;
  padding: 4px 0;
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--white); }
.footer-col select {
  background: var(--bg-card);
  color: var(--gray);
  border: 1px solid rgba(255, 255, 255, 0.1);
  padding: 8px 12px;
  font-family: var(--font-body);
  font-size: 0.85rem;
  width: 100%;
  max-width: 200px;
  margin-top: 8px;
  outline: none;
  cursor: pointer;
}
.footer-col select:focus { border-color: var(--red); }
.footer-bottom {
  border-top: 1px solid rgba(255, 255, 255, 0.06);
  padding-top: 30px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.8rem;
  color: var(--gray-dark);
}
.footer-logo {
  font-family: var(--font-heading);
  font-size: 1.1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 2px;
}
.footer-logo span { color: var(--red); }

/* METHOD OVERVIEW */
.method { background: var(--bg-light); }
.method-content {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}
.method-content p {
  color: var(--gray);
  font-size: 1.05rem;
  line-height: 1.8;
}

/* TOGGLE */
.toggle-section { text-align: center; }
.toggle-controls {
  display: flex;
  justify-content: center;
  gap: 0;
  margin-bottom: 40px;
}
.toggle-btn {
  background: var(--bg-card);
  color: var(--gray);
  padding: 14px 40px;
  font-family: var(--font-heading);
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  transition: all var(--transition);
}
.toggle-btn.active {
  background: var(--red);
  color: var(--white);
  border-color: var(--red);
}
.toggle-btn:hover:not(.active) { background: var(--bg-card-hover); color: var(--white); }
.toggle-content {
  max-width: 700px;
  margin: 0 auto;
  color: var(--gray);
  line-height: 1.8;
  font-size: 1.05rem;
}
.toggle-panel {
  display: none;
  animation: fadeIn 0.4s ease;
}
.toggle-panel.active { display: block; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }

/* SCHEDULE TABLE */
.schedule { background: var(--bg); }
.schedule-table {
  width: 100%;
  max-width: 700px;
  margin: 0 auto;
  border-collapse: collapse;
}
.schedule-table th,
.schedule-table td {
  padding: 18px 24px;
  text-align: left;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}
.schedule-table th {
  font-family: var(--font-heading);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--red);
  background: var(--bg-card);
}
.schedule-table td {
  font-size: 0.95rem;
  color: var(--gray-light);
}
.schedule-table tr:hover td { background: rgba(255, 0, 0, 0.03); }
.schedule-table td:first-child {
  font-family: var(--font-heading);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--white);
}

/* INSTRUCTOR GRID */
.instructor-section { background: var(--bg-light); }
.filter-controls {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-bottom: 50px;
  flex-wrap: wrap;
}
.filter-btn {
  background: var(--bg-card);
  color: var(--gray);
  padding: 10px 24px;
  font-family: var(--font-heading);
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  transition: all var(--transition);
}
.filter-btn.active {
  background: var(--red);
  color: var(--white);
  border-color: var(--red);
}
.filter-btn:hover:not(.active) { background: var(--bg-card-hover); color: var(--white); }
.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 24px;
}
.instructor-card {
  background: var(--bg-card);
  border: 1px solid rgba(255, 255, 255, 0.06);
  padding: 0;
  overflow: hidden;
  transition: all var(--transition);
}
.instructor-card:hover {
  border-color: rgba(255, 0, 0, 0.3);
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.4);
}
.instructor-photo {
  width: 100%;
  aspect-ratio: 1;
  background: linear-gradient(135deg, #1a1a1a 0%, #2a2a2a 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 3rem;
  color: var(--red);
  opacity: 0.4;
}
.instructor-info { padding: 24px; }
.instructor-info h3 {
  font-family: var(--font-heading);
  font-size: 1.2rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  margin-bottom: 6px;
}
.instructor-info .location {
  color: var(--red);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 16px;
}
.instructor-info .book-link {
  font-family: var(--font-heading);
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--gray);
  transition: color var(--transition);
  border-bottom: 1px solid transparent;
  padding-bottom: 2px;
}
.instructor-info .book-link:hover { color: var(--red); border-bottom-color: var(--red); }
.instructor-card.hidden {
  display: none;
}

/* FAQ ACCORDION */
.faq-section { background: var(--bg-light); }
.faq-list {
  max-width: 800px;
  margin: 0 auto;
}
.faq-item {
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}
.faq-question {
  width: 100%;
  background: none;
  color: var(--white);
  padding: 24px 0;
  font-family: var(--font-heading);
  font-size: 1.1rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  text-align: left;
  display: flex;
  justify-content: space-between;
  align-items: center;
  transition: color var(--transition);
}
.faq-question:hover { color: var(--red); }
.faq-question .icon {
  font-size: 1.5rem;
  transition: transform var(--transition);
  color: var(--red);
  flex-shrink: 0;
  margin-left: 20px;
}
.faq-item.active .faq-question .icon { transform: rotate(45deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}
.faq-item.active .faq-answer { max-height: 300px; }
.faq-answer p {
  color: var(--gray);
  line-height: 1.8;
  padding-bottom: 24px;
  font-size: 0.95rem;
}

/* DIGITAL FEATURES */
.features-section { background: var(--bg); }
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 30px;
}
.feature-card {
  background: var(--bg-card);
  border: 1px solid rgba(255, 255, 255, 0.06);
  padding: 40px 30px;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}
.feature-card::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0; right: 0;
  height: 3px;
  background: var(--red);
  transform: scaleX(0);
  transition: transform var(--transition);
}
.feature-card:hover::after { transform: scaleX(1); }
.feature-card:hover { border-color: rgba(255, 0, 0, 0.15); transform: translateY(-4px); }
.feature-card h3 {
  font-family: var(--font-heading);
  font-size: 1.2rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  margin-bottom: 12px;
  color: var(--red);
}
.feature-card p {
  color: var(--gray);
  line-height: 1.7;
  font-size: 0.93rem;
}

/* CTA BANNER */
.cta-banner {
  background: var(--bg-card);
  text-align: center;
  padding: 80px 0;
  border-top: 3px solid var(--red);
}

/* PAGE HERO (shorter) */
.page-hero {
  min-height: 45vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: linear-gradient(135deg, rgba(255, 0, 0, 0.1) 0%, var(--bg) 60%);
  position: relative;
}
.page-hero::before {
  content: '';
  position: absolute;
  bottom: 0; left: 0; right: 0;
  height: 100px;
  background: linear-gradient(to top, var(--bg-light), transparent);
  pointer-events: none;
}
.page-hero h1 {
  font-family: var(--font-heading);
  font-size: clamp(2.2rem, 5vw, 4rem);
  text-transform: uppercase;
  letter-spacing: 4px;
  font-weight: 700;
  line-height: 1.15;
}
.page-hero h1 span { color: var(--red); }
.page-hero p {
  color: var(--gray);
  font-size: 1.05rem;
  margin-top: 16px;
  max-width: 550px;
  margin-left: auto;
  margin-right: auto;
}

/* MOBILE NAV */
.mobile-nav {
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100vh;
  background: rgba(10, 10, 10, 0.98);
  z-index: 999;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 24px;
}
.mobile-nav.open { display: flex; }
.mobile-nav a {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  text-transform: uppercase;
  letter-spacing: 3px;
  color: var(--gray-light);
  transition: color var(--transition);
}
.mobile-nav a:hover { color: var(--red); }
.mobile-nav-close {
  position: absolute;
  top: 24px;
  right: 24px;
  background: none;
  color: var(--white);
  font-size: 2rem;
}

/* RESPONSIVE */
@media (max-width: 1024px) {
  .nav-links { display: none; }
  .nav-utility { display: none; }
  .hamburger { display: flex; }
}

@media (max-width: 768px) {
  section { padding: 70px 0; }
  .hero { min-height: 70vh; }
  .two-ways-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 30px; }
  .footer-bottom { flex-direction: column; gap: 12px; text-align: center; }
  .newsletter-form { flex-direction: column; }
  .newsletter-form button { padding: 16px; }
  .schedule-table th, .schedule-table td { padding: 14px 16px; }
  .filter-controls { gap: 8px; }
  .filter-btn { padding: 8px 16px; font-size: 0.7rem; }
  .features-grid { grid-template-columns: 1fr; }
}

@media (max-width: 480px) {
  .hero-btns { flex-direction: column; align-items: center; }
  .btn-primary, .btn-secondary { width: 100%; text-align: center; }
  .footer-grid { grid-template-columns: 1fr; }
  .page-hero { min-height: 35vh; }
}

@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@300;400;500;600&display=swap');

*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --red: #FF0000;
  --red-hover: #cc0000;
  --red-dark: #990000;
  --bg: #141414;
  --bg-light: #1a1a1a;
  --bg-card: #1e1e1e;
  --bg-card-hover: #252525;
  --white: #FFFFFF;
  --gray: #b0b0b0;
  --gray-light: #d0d0d0;
  --gray-dark: #666;
  --font-heading: 'Oswald', sans-serif;
  --font-body: 'Inter', sans-serif;
  --transition: 0.3s ease;
  --max-width: 1200px;
}

html { scroll-behavior: smooth; font-size: 16px; }

body {
  background: var(--bg);
  color: var(--white);
  font-family: var(--font-body);
  line-height: 1.6;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
ul { list-style: none; }
img { max-width: 100%; display: block; }
button { cursor: pointer; border: none; font-family: var(--font-body); }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* TOP BAR */
.top-bar {
  background: var(--red);
  text-align: center;
  padding: 10px 16px;
  font-family: var(--font-heading);
  font-size: 0.85rem;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  font-weight: 500;
}
.top-bar a {
  color: var(--white);
  text-decoration: underline;
  margin-left: 10px;
  font-weight: 600;
}

/* NAVBAR */
.navbar {
  background: rgba(20, 20, 20, 0.95);
  backdrop-filter: blur(12px);
  position: sticky;
  top: 0;
  z-index: 1000;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}
.navbar .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 0;
  padding-bottom: 0;
  height: 70px;
}
.nav-logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--white);
}
.nav-logo span { color: var(--red); }

.nav-links {
  display: flex;
  gap: 28px;
  align-items: center;
}
.nav-links a {
  font-family: var(--font-heading);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--gray-light);
  transition: color var(--transition);
  position: relative;
  padding: 4px 0;
}
.nav-links a::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--red);
  transition: width var(--transition);
}
.nav-links a:hover { color: var(--white); }
.nav-links a:hover::after { width: 100%; }
.nav-links a.active { color: var(--red); }

.nav-utility {
  display: flex;
  gap: 16px;
  align-items: center;
}
.nav-utility a {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--gray);
  transition: color var(--transition);
}
.nav-utility a:hover { color: var(--white); }

.btn-book {
  background: var(--red);
  color: var(--white);
  padding: 10px 24px;
  font-family: var(--font-heading);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  font-weight: 600;
  border-radius: 0;
  transition: background var(--transition), transform var(--transition);
  display: inline-block;
}
.btn-book:hover { background: var(--red-hover); transform: translateY(-1px); }

/* HAMBURGER */
.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  padding: 8px;
}
.hamburger span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--white);
  transition: var(--transition);
}

/* HERO */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: linear-gradient(135deg, rgba(255, 0, 0, 0.15) 0%, rgba(20, 20, 20, 1) 50%, rgba(20, 20, 20, 1) 100%);
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background: radial-gradient(ellipse at center top, rgba(255, 0, 0, 0.08) 0%, transparent 70%);
  pointer-events: none;
}
.hero-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
  padding: 40px 24px;
}
.hero h1 {
  font-family: var(--font-heading);
  font-size: clamp(2.5rem, 6vw, 5rem);
  text-transform: uppercase;
  letter-spacing: 4px;
  line-height: 1.1;
  font-weight: 700;
  margin-bottom: 20px;
}
.hero h1 span { color: var(--red); }
.hero p {
  font-size: 1.1rem;
  color: var(--gray-light);
  margin-bottom: 36px;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
  line-height: 1.7;
}
.hero-btns {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}
.btn-primary {
  background: var(--red);
  color: var(--white);
  padding: 16px 48px;
  font-family: var(--font-heading);
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 3px;
  font-weight: 600;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
  display: inline-block;
}
.btn-primary:hover {
  background: var(--red-hover);
  transform: translateY(-2px);
  box-shadow: 0 8px 30px rgba(255, 0, 0, 0.3);
}
.btn-secondary {
  background: transparent;
  color: var(--white);
  padding: 16px 48px;
  font-family: var(--font-heading);
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 3px;
  font-weight: 600;
  border: 2px solid var(--white);
  transition: all var(--transition);
  display: inline-block;
}
.btn-secondary:hover {
  background: var(--white);
  color: var(--bg);
  transform: translateY(-2px);
}

/* SECTIONS */
section { padding: 100px 0; }
.section-heading {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3.5rem);
  text-transform: uppercase;
  letter-spacing: 3px;
  text-align: center;
  margin-bottom: 20px;
  font-weight: 700;
  line-height: 1.15;
}
.section-heading span { color: var(--red); }
.section-subtext {
  text-align: center;
  color: var(--gray);
  max-width: 700px;
  margin: 0 auto 60px;
  font-size: 1.05rem;
  line-height: 1.7;
}

/* COMMUNITY PROMO */
.community {
  background: var(--bg-light);
  text-align: center;
}

/* TWO WAYS */
.two-ways-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 30px;
  margin-top: 50px;
}
.way-card {
  background: var(--bg-card);
  border: 1px solid rgba(255, 255, 255, 0.06);
  padding: 50px 40px;
  text-align: center;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}
.way-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: var(--red);
  transform: scaleX(0);
  transition: transform var(--transition);
}
.way-card:hover::before { transform: scaleX(1); }
.way-card:hover { border-color: rgba(255, 0, 0, 0.2); transform: translateY(-4px); }
.way-card h3 {
  font-family: var(--font-heading);
  font-size: 1.8rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 16px;
  color: var(--red);
}
.way-card p {
  color: var(--gray);
  line-height: 1.7;
  font-size: 0.95rem;
}

/* STUDIO EXPERIENCE */
.studio {
  background: linear-gradient(to bottom, var(--bg), var(--bg-light));
  text-align: center;
}
.studio-cta {
  margin-top: 50px;
  font-family: var(--font-heading);
  font-size: 1.1rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--gray-light);
  line-height: 1.6;
}

/* FREE TRIAL */
.free-trial {
  background: var(--red);
  text-align: center;
  padding: 80px 0;
  position: relative;
  overflow: hidden;
}
.free-trial::before {
  content: '';
  position: absolute;
  top: -50%; left: -50%;
  width: 200%;
  height: 200%;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.05) 0%, transparent 60%);
  pointer-events: none;
}
.free-trial h2 {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3.5rem);
  text-transform: uppercase;
  letter-spacing: 4px;
  margin-bottom: 30px;
  position: relative;
}
.free-trial .btn-primary {
  background: var(--white);
  color: var(--red);
  position: relative;
}
.free-trial .btn-primary:hover {
  background: var(--bg);
  color: var(--white);
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.4);
}

/* CAROUSEL */
.carousel-section { background: var(--bg-light); overflow: hidden; }
.carousel-wrapper {
  position: relative;
  max-width: 1000px;
  margin: 0 auto;
  overflow: hidden;
}
.carousel-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}
.carousel-slide {
  min-width: 100%;
  aspect-ratio: 16/9;
  background: var(--bg-card);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.carousel-slide-inner {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 1.5rem;
  text-transform: uppercase;
  letter-spacing: 3px;
  color: var(--gray-dark);
  background: linear-gradient(135deg, var(--bg-card) 0%, #222 100%);
}
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  background: rgba(255, 0, 0, 0.85);
  color: var(--white);
  width: 50px;
  height: 50px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.4rem;
  z-index: 10;
  transition: all var(--transition);
}
.carousel-btn:hover { background: var(--red); transform: translateY(-50%) scale(1.05); }
.carousel-btn.prev { left: 16px; }
.carousel-btn.next { right: 16px; }
.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-top: 24px;
}
.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--gray-dark);
  border: none;
  transition: all var(--transition);
}
.carousel-dot.active { background: var(--red); transform: scale(1.3); }

/* NEWSLETTER */
.newsletter {
  background: var(--bg);
  text-align: center;
  padding: 80px 0;
  border-top: 1px solid rgba(255, 255, 255, 0.04);
}
.newsletter-form {
  display: flex;
  gap: 0;
  max-width: 500px;
  margin: 0 auto;
}
.newsletter-form input[type="email"] {
  flex: 1;
  padding: 16px 20px;
  background: var(--bg-card);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: var(--white);
  font-family: var(--font-body);
  font-size: 0.95rem;
  outline: none;
  transition: border-color var(--transition);
}
.newsletter-form input[type="email"]::placeholder { color: var(--gray-dark); }
.newsletter-form input[type="email"]:focus { border-color: var(--red); }
.newsletter-form input[type="email"].error { border-color: #ff4444; }
.newsletter-form input[type="email"].success { border-color: #44bb44; }
.newsletter-form button {
  background: var(--red);
  color: var(--white);
  padding: 16px 32px;
  font-family: var(--font-heading);
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  font-weight: 600;
  transition: background var(--transition);
  white-space: nowrap;
}
.newsletter-form button:hover { background: var(--red-hover); }
.newsletter-msg {
  margin-top: 12px;
  font-size: 0.85rem;
  min-height: 20px;
}
.newsletter-msg.error { color: #ff4444; }
.newsletter-msg.success { color: #44bb44; }

/* FOOTER */
.footer {
  background: #0a0a0a;
  padding: 80px 0 40px;
  border-top: 1px solid rgba(255, 255, 255, 0.04);
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 50px;
}
.footer-col h4 {
  font-family: var(--font-heading);
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 20px;
  color: var(--red);
}
.footer-col a {
  display: block;
  color: var(--gray);
  font-size: 0.9rem;
  padding: 4px 0;
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--white); }
.footer-col select {
  background: var(--bg-card);
  color: var(--gray);
  border: 1px solid rgba(255, 255, 255, 0.1);
  padding: 8px 12px;
  font-family: var(--font-body);
  font-size: 0.85rem;
  width: 100%;
  max-width: 200px;
  margin-top: 8px;
  outline: none;
  cursor: pointer;
}
.footer-col select:focus { border-color: var(--red); }
.footer-bottom {
  border-top: 1px solid rgba(255, 255, 255, 0.06);
  padding-top: 30px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.8rem;
  color: var(--gray-dark);
}
.footer-logo {
  font-family: var(--font-heading);
  font-size: 1.1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 2px;
}
.footer-logo span { color: var(--red); }

/* METHOD OVERVIEW */
.method { background: var(--bg-light); }
.method-content {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}
.method-content p {
  color: var(--gray);
  font-size: 1.05rem;
  line-height: 1.8;
}

/* TOGGLE */
.toggle-section { text-align: center; }
.toggle-controls {
  display: flex;
  justify-content: center;
  gap: 0;
  margin-bottom: 40px;
}
.toggle-btn {
  background: var(--bg-card);
  color: var(--gray);
  padding: 14px 40px;
  font-family: var(--font-heading);
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  transition: all var(--transition);
}
.toggle-btn.active {
  background: var(--red);
  color: var(--white);
  border-color: var(--red);
}
.toggle-btn:hover:not(.active) { background: var(--bg-card-hover); color: var(--white); }
.toggle-content {
  max-width: 700px;
  margin: 0 auto;
  color: var(--gray);
  line-height: 1.8;
  font-size: 1.05rem;
}
.toggle-panel {
  display: none;
  animation: fadeIn 0.4s ease;
}
.toggle-panel.active { display: block; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }

/* SCHEDULE TABLE */
.schedule { background: var(--bg); }
.schedule-table {
  width: 100%;
  max-width: 700px;
  margin: 0 auto;
  border-collapse: collapse;
}
.schedule-table th,
.schedule-table td {
  padding: 18px 24px;
  text-align: left;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}
.schedule-table th {
  font-family: var(--font-heading);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--red);
  background: var(--bg-card);
}
.schedule-table td {
  font-size: 0.95rem;
  color: var(--gray-light);
}
.schedule-table tr:hover td { background: rgba(255, 0, 0, 0.03); }
.schedule-table td:first-child {
  font-family: var(--font-heading);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--white);
}

/* INSTRUCTOR GRID */
.instructor-section { background: var(--bg-light); }
.filter-controls {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-bottom: 50px;
  flex-wrap: wrap;
}
.filter-btn {
  background: var(--bg-card);
  color: var(--gray);
  padding: 10px 24px;
  font-family: var(--font-heading);
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  transition: all var(--transition);
}
.filter-btn.active {
  background: var(--red);
  color: var(--white);
  border-color: var(--red);
}
.filter-btn:hover:not(.active) { background: var(--bg-card-hover); color: var(--white); }
.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 24px;
}
.instructor-card {
  background: var(--bg-card);
  border: 1px solid rgba(255, 255, 255, 0.06);
  padding: 0;
  overflow: hidden;
  transition: all var(--transition);
}
.instructor-card:hover {
  border-color: rgba(255, 0, 0, 0.3);
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.4);
}
.instructor-photo {
  width: 100%;
  aspect-ratio: 1;
  background: linear-gradient(135deg, #1a1a1a 0%, #2a2a2a 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 3rem;
  color: var(--red);
  opacity: 0.4;
}
.instructor-info { padding: 24px; }
.instructor-info h3 {
  font-family: var(--font-heading);
  font-size: 1.2rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  margin-bottom: 6px;
}
.instructor-info .location {
  color: var(--red);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 16px;
}
.instructor-info .book-link {
  font-family: var(--font-heading);
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--gray);
  transition: color var(--transition);
  border-bottom: 1px solid transparent;
  padding-bottom: 2px;
}
.instructor-info .book-link:hover { color: var(--red); border-bottom-color: var(--red); }
.instructor-card.hidden {
  display: none;
}

/* FAQ ACCORDION */
.faq-section { background: var(--bg-light); }
.faq-list {
  max-width: 800px;
  margin: 0 auto;
}
.faq-item {
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}
.faq-question {
  width: 100%;
  background: none;
  color: var(--white);
  padding: 24px 0;
  font-family: var(--font-heading);
  font-size: 1.1rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  text-align: left;
  display: flex;
  justify-content: space-between;
  align-items: center;
  transition: color var(--transition);
}
.faq-question:hover { color: var(--red); }
.faq-question .icon {
  font-size: 1.5rem;
  transition: transform var(--transition);
  color: var(--red);
  flex-shrink: 0;
  margin-left: 20px;
}
.faq-item.active .faq-question .icon { transform: rotate(45deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}
.faq-item.active .faq-answer { max-height: 300px; }
.faq-answer p {
  color: var(--gray);
  line-height: 1.8;
  padding-bottom: 24px;
  font-size: 0.95rem;
}

/* DIGITAL FEATURES */
.features-section { background: var(--bg); }
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 30px;
}
.feature-card {
  background: var(--bg-card);
  border: 1px solid rgba(255, 255, 255, 0.06);
  padding: 40px 30px;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}
.feature-card::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0; right: 0;
  height: 3px;
  background: var(--red);
  transform: scaleX(0);
  transition: transform var(--transition);
}
.feature-card:hover::after { transform: scaleX(1); }
.feature-card:hover { border-color: rgba(255, 0, 0, 0.15); transform: translateY(-4px); }
.feature-card h3 {
  font-family: var(--font-heading);
  font-size: 1.2rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  margin-bottom: 12px;
  color: var(--red);
}
.feature-card p {
  color: var(--gray);
  line-height: 1.7;
  font-size: 0.93rem;
}

/* CTA BANNER */
.cta-banner {
  background: var(--bg-card);
  text-align: center;
  padding: 80px 0;
  border-top: 3px solid var(--red);
}

/* PAGE HERO (shorter) */
.page-hero {
  min-height: 45vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: linear-gradient(135deg, rgba(255, 0, 0, 0.1) 0%, var(--bg) 60%);
  position: relative;
}
.page-hero::before {
  content: '';
  position: absolute;
  bottom: 0; left: 0; right: 0;
  height: 100px;
  background: linear-gradient(to top, var(--bg-light), transparent);
  pointer-events: none;
}
.page-hero h1 {
  font-family: var(--font-heading);
  font-size: clamp(2.2rem, 5vw, 4rem);
  text-transform: uppercase;
  letter-spacing: 4px;
  font-weight: 700;
  line-height: 1.15;
}
.page-hero h1 span { color: var(--red); }
.page-hero p {
  color: var(--gray);
  font-size: 1.05rem;
  margin-top: 16px;
  max-width: 550px;
  margin-left: auto;
  margin-right: auto;
}

/* MOBILE NAV */
.mobile-nav {
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100vh;
  background: rgba(10, 10, 10, 0.98);
  z-index: 999;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 24px;
}
.mobile-nav.open { display: flex; }
.mobile-nav a {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  text-transform: uppercase;
  letter-spacing: 3px;
  color: var(--gray-light);
  transition: color var(--transition);
}
.mobile-nav a:hover { color: var(--red); }
.mobile-nav-close {
  position: absolute;
  top: 24px;
  right: 24px;
  background: none;
  color: var(--white);
  font-size: 2rem;
}

/* RESPONSIVE */
@media (max-width: 1024px) {
  .nav-links { display: none; }
  .nav-utility { display: none; }
  .hamburger { display: flex; }
}

@media (max-width: 768px) {
  section { padding: 70px 0; }
  .hero { min-height: 70vh; }
  .two-ways-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 30px; }
  .footer-bottom { flex-direction: column; gap: 12px; text-align: center; }
  .newsletter-form { flex-direction: column; }
  .newsletter-form button { padding: 16px; }
  .schedule-table th, .schedule-table td { padding: 14px 16px; }
  .filter-controls { gap: 8px; }
  .filter-btn { padding: 8px 16px; font-size: 0.7rem; }
  .features-grid { grid-template-columns: 1fr; }
}

@media (max-width: 480px) {
  .hero-btns { flex-direction: column; align-items: center; }
  .btn-primary, .btn-secondary { width: 100%; text-align: center; }
  .footer-grid { grid-template-columns: 1fr; }
  .page-hero { min-height: 35vh; }
}

raw_arguments.content:
@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@300;400;500;600&display=swap');

*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --red: #FF0000;
  --red-hover: #cc0000;
  --red-dark: #990000;
  --bg: #141414;
  --bg-light: #1a1a1a;
  --bg-card: #1e1e1e;
  --bg-card-hover: #252525;
  --white: #FFFFFF;
  --gray: #b0b0b0;
  --gray-light: #d0d0d0;
  --gray-dark: #666;
  --font-heading: 'Oswald', sans-serif;
  --font-body: 'Inter', sans-serif;
  --transition: 0.3s ease;
  --max-width: 1200px;
}

html { scroll-behavior: smooth; font-size: 16px; }

body {
  background: var(--bg);
  color: var(--white);
  font-family: var(--font-body);
  line-height: 1.6;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
ul { list-style: none; }
img { max-width: 100%; display: block; }
button { cursor: pointer; border: none; font-family: var(--font-body); }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* TOP BAR */
.top-bar {
  background: var(--red);
  text-align: center;
  padding: 10px 16px;
  font-family: var(--font-heading);
  font-size: 0.85rem;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  font-weight: 500;
}
.top-bar a {
  color: var(--white);
  text-decoration: underline;
  margin-left: 10px;
  font-weight: 600;
}

/* NAVBAR */
.navbar {
  background: rgba(20, 20, 20, 0.95);
  backdrop-filter: blur(12px);
  position: sticky;
  top: 0;
  z-index: 1000;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}
.navbar .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 0;
  padding-bottom: 0;
  height: 70px;
}
.nav-logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--white);
}
.nav-logo span { color: var(--red); }

.nav-links {
  display: flex;
  gap: 28px;
  align-items: center;
}
.nav-links a {
  font-family: var(--font-heading);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--gray-light);
  transition: color var(--transition);
  position: relative;
  padding: 4px 0;
}
.nav-links a::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--red);
  transition: width var(--transition);
}
.nav-links a:hover { color: var(--white); }
.nav-links a:hover::after { width: 100%; }
.nav-links a.active { color: var(--red); }

.nav-utility {
  display: flex;
  gap: 16px;
  align-items: center;
}
.nav-utility a {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--gray);
  transition: color var(--transition);
}
.nav-utility a:hover { color: var(--white); }

.btn-book {
  background: var(--red);
  color: var(--white);
  padding: 10px 24px;
  font-family: var(--font-heading);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  font-weight: 600;
  border-radius: 0;
  transition: background var(--transition), transform var(--transition);
  display: inline-block;
}
.btn-book:hover { background: var(--red-hover); transform: translateY(-1px); }

/* HAMBURGER */
.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  padding: 8px;
}
.hamburger span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--white);
  transition: var(--transition);
}

/* HERO */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: linear-gradient(135deg, rgba(255, 0, 0, 0.15) 0%, rgba(20, 20, 20, 1) 50%, rgba(20, 20, 20, 1) 100%);
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background: radial-gradient(ellipse at center top, rgba(255, 0, 0, 0.08) 0%, transparent 70%);
  pointer-events: none;
}
.hero-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
  padding: 40px 24px;
}
.hero h1 {
  font-family: var(--font-heading);
  font-size: clamp(2.5rem, 6vw, 5rem);
  text-transform: uppercase;
  letter-spacing: 4px;
  line-height: 1.1;
  font-weight: 700;
  margin-bottom: 20px;
}
.hero h1 span { color: var(--red); }
.hero p {
  font-size: 1.1rem;
  color: var(--gray-light);
  margin-bottom: 36px;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
  line-height: 1.7;
}
.hero-btns {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}
.btn-primary {
  background: var(--red);
  color: var(--white);
  padding: 16px 48px;
  font-family: var(--font-heading);
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 3px;
  font-weight: 600;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
  display: inline-block;
}
.btn-primary:hover {
  background: var(--red-hover);
  transform: translateY(-2px);
  box-shadow: 0 8px 30px rgba(255, 0, 0, 0.3);
}
.btn-secondary {
  background: transparent;
  color: var(--white);
  padding: 16px 48px;
  font-family: var(--font-heading);
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 3px;
  font-weight: 600;
  border: 2px solid var(--white);
  transition: all var(--transition);
  display: inline-block;
}
.btn-secondary:hover {
  background: var(--white);
  color: var(--bg);
  transform: translateY(-2px);
}

/* SECTIONS */
section { padding: 100px 0; }
.section-heading {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3.5rem);
  text-transform: uppercase;
  letter-spacing: 3px;
  text-align: center;
  margin-bottom: 20px;
  font-weight: 700;
  line-height: 1.15;
}
.section-heading span { color: var(--red); }
.section-subtext {
  text-align: center;
  color: var(--gray);
  max-width: 700px;
  margin: 0 auto 60px;
  font-size: 1.05rem;
  line-height: 1.7;
}

/* COMMUNITY PROMO */
.community {
  background: var(--bg-light);
  text-align: center;
}

/* TWO WAYS */
.two-ways-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 30px;
  margin-top: 50px;
}
.way-card {
  background: var(--bg-card);
  border: 1px solid rgba(255, 255, 255, 0.06);
  padding: 50px 40px;
  text-align: center;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}
.way-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: var(--red);
  transform: scaleX(0);
  transition: transform var(--transition);
}
.way-card:hover::before { transform: scaleX(1); }
.way-card:hover { border-color: rgba(255, 0, 0, 0.2); transform: translateY(-4px); }
.way-card h3 {
  font-family: var(--font-heading);
  font-size: 1.8rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 16px;
  color: var(--red);
}
.way-card p {
  color: var(--gray);
  line-height: 1.7;
  font-size: 0.95rem;
}

/* STUDIO EXPERIENCE */
.studio {
  background: linear-gradient(to bottom, var(--bg), var(--bg-light));
  text-align: center;
}
.studio-cta {
  margin-top: 50px;
  font-family: var(--font-heading);
  font-size: 1.1rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--gray-light);
  line-height: 1.6;
}

/* FREE TRIAL */
.free-trial {
  background: var(--red);
  text-align: center;
  padding: 80px 0;
  position: relative;
  overflow: hidden;
}
.free-trial::before {
  content: '';
  position: absolute;
  top: -50%; left: -50%;
  width: 200%;
  height: 200%;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.05) 0%, transparent 60%);
  pointer-events: none;
}
.free-trial h2 {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3.5rem);
  text-transform: uppercase;
  letter-spacing: 4px;
  margin-bottom: 30px;
  position: relative;
}
.free-trial .btn-primary {
  background: var(--white);
  color: var(--red);
  position: relative;
}
.free-trial .btn-primary:hover {
  background: var(--bg);
  color: var(--white);
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.4);
}

/* CAROUSEL */
.carousel-section { background: var(--bg-light); overflow: hidden; }
.carousel-wrapper {
  position: relative;
  max-width: 1000px;
  margin: 0 auto;
  overflow: hidden;
}
.carousel-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}
.carousel-slide {
  min-width: 100%;
  aspect-ratio: 16/9;
  background: var(--bg-card);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.carousel-slide-inner {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 1.5rem;
  text-transform: uppercase;
  letter-spacing: 3px;
  color: var(--gray-dark);
  background: linear-gradient(135deg, var(--bg-card) 0%, #222 100%);
}
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  background: rgba(255, 0, 0, 0.85);
  color: var(--white);
  width: 50px;
  height: 50px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.4rem;
  z-index: 10;
  transition: all var(--transition);
}
.carousel-btn:hover { background: var(--red); transform: translateY(-50%) scale(1.05); }
.carousel-btn.prev { left: 16px; }
.carousel-btn.next { right: 16px; }
.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-top: 24px;
}
.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--gray-dark);
  border: none;
  transition: all var(--transition);
}
.carousel-dot.active { background: var(--red); transform: scale(1.3); }

/* NEWSLETTER */
.newsletter {
  background: var(--bg);
  text-align: center;
  padding: 80px 0;
  border-top: 1px solid rgba(255, 255, 255, 0.04);
}
.newsletter-form {
  display: flex;
  gap: 0;
  max-width: 500px;
  margin: 0 auto;
}
.newsletter-form input[type="email"] {
  flex: 1;
  padding: 16px 20px;
  background: var(--bg-card);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: var(--white);
  font-family: var(--font-body);
  font-size: 0.95rem;
  outline: none;
  transition: border-color var(--transition);
}
.newsletter-form input[type="email"]::placeholder { color: var(--gray-dark); }
.newsletter-form input[type="email"]:focus { border-color: var(--red); }
.newsletter-form input[type="email"].error { border-color: #ff4444; }
.newsletter-form input[type="email"].success { border-color: #44bb44; }
.newsletter-form button {
  background: var(--red);
  color: var(--white);
  padding: 16px 32px;
  font-family: var(--font-heading);
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  font-weight: 600;
  transition: background var(--transition);
  white-space: nowrap;
}
.newsletter-form button:hover { background: var(--red-hover); }
.newsletter-msg {
  margin-top: 12px;
  font-size: 0.85rem;
  min-height: 20px;
}
.newsletter-msg.error { color: #ff4444; }
.newsletter-msg.success { color: #44bb44; }

/* FOOTER */
.footer {
  background: #0a0a0a;
  padding: 80px 0 40px;
  border-top: 1px solid rgba(255, 255, 255, 0.04);
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 50px;
}
.footer-col h4 {
  font-family: var(--font-heading);
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 20px;
  color: var(--red);
}
.footer-col a {
  display: block;
  color: var(--gray);
  font-size: 0.9rem;
  padding: 4px 0;
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--white); }
.footer-col select {
  background: var(--bg-card);
  color: var(--gray);
  border: 1px solid rgba(255, 255, 255, 0.1);
  padding: 8px 12px;
  font-family: var(--font-body);
  font-size: 0.85rem;
  width: 100%;
  max-width: 200px;
  margin-top: 8px;
  outline: none;
  cursor: pointer;
}
.footer-col select:focus { border-color: var(--red); }
.footer-bottom {
  border-top: 1px solid rgba(255, 255, 255, 0.06);
  padding-top: 30px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.8rem;
  color: var(--gray-dark);
}
.footer-logo {
  font-family: var(--font-heading);
  font-size: 1.1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 2px;
}
.footer-logo span { color: var(--red); }

/* METHOD OVERVIEW */
.method { background: var(--bg-light); }
.method-content {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}
.method-content p {
  color: var(--gray);
  font-size: 1.05rem;
  line-height: 1.8;
}

/* TOGGLE */
.toggle-section { text-align: center; }
.toggle-controls {
  display: flex;
  justify-content: center;
  gap: 0;
  margin-bottom: 40px;
}
.toggle-btn {
  background: var(--bg-card);
  color: var(--gray);
  padding: 14px 40px;
  font-family: var(--font-heading);
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  transition: all var(--transition);
}
.toggle-btn.active {
  background: var(--red);
  color: var(--white);
  border-color: var(--red);
}
.toggle-btn:hover:not(.active) { background: var(--bg-card-hover); color: var(--white); }
.toggle-content {
  max-width: 700px;
  margin: 0 auto;
  color: var(--gray);
  line-height: 1.8;
  font-size: 1.05rem;
}
.toggle-panel {
  display: none;
  animation: fadeIn 0.4s ease;
}
.toggle-panel.active { display: block; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }

/* SCHEDULE TABLE */
.schedule { background: var(--bg); }
.schedule-table {
  width: 100%;
  max-width: 700px;
  margin: 0 auto;
  border-collapse: collapse;
}
.schedule-table th,
.schedule-table td {
  padding: 18px 24px;
  text-align: left;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}
.schedule-table th {
  font-family: var(--font-heading);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--red);
  background: var(--bg-card);
}
.schedule-table td {
  font-size: 0.95rem;
  color: var(--gray-light);
}
.schedule-table tr:hover td { background: rgba(255, 0, 0, 0.03); }
.schedule-table td:first-child {
  font-family: var(--font-heading);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--white);
}

/* INSTRUCTOR GRID */
.instructor-section { background: var(--bg-light); }
.filter-controls {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-bottom: 50px;
  flex-wrap: wrap;
}
.filter-btn {
  background: var(--bg-card);
  color: var(--gray);
  padding: 10px 24px;
  font-family: var(--font-heading);
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  transition: all var(--transition);
}
.filter-btn.active {
  background: var(--red);
  color: var(--white);
  border-color: var(--red);
}
.filter-btn:hover:not(.active) { background: var(--bg-card-hover); color: var(--white); }
.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 24px;
}
.instructor-card {
  background: var(--bg-card);
  border: 1px solid rgba(255, 255, 255, 0.06);
  padding: 0;
  overflow: hidden;
  transition: all var(--transition);
}
.instructor-card:hover {
  border-color: rgba(255, 0, 0, 0.3);
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.4);
}
.instructor-photo {
  width: 100%;
  aspect-ratio: 1;
  background: linear-gradient(135deg, #1a1a1a 0%, #2a2a2a 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 3rem;
  color: var(--red);
  opacity: 0.4;
}
.instructor-info { padding: 24px; }
.instructor-info h3 {
  font-family: var(--font-heading);
  font-size: 1.2rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  margin-bottom: 6px;
}
.instructor-info .location {
  color: var(--red);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 16px;
}
.instructor-info .book-link {
  font-family: var(--font-heading);
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--gray);
  transition: color var(--transition);
  border-bottom: 1px solid transparent;
  padding-bottom: 2px;
}
.instructor-info .book-link:hover { color: var(--red); border-bottom-color: var(--red); }
.instructor-card.hidden {
  display: none;
}

/* FAQ ACCORDION */
.faq-section { background: var(--bg-light); }
.faq-list {
  max-width: 800px;
  margin: 0 auto;
}
.faq-item {
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}
.faq-question {
  width: 100%;
  background: none;
  color: var(--white);
  padding: 24px 0;
  font-family: var(--font-heading);
  font-size: 1.1rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  text-align: left;
  display: flex;
  justify-content: space-between;
  align-items: center;
  transition: color var(--transition);
}
.faq-question:hover { color: var(--red); }
.faq-question .icon {
  font-size: 1.5rem;
  transition: transform var(--transition);
  color: var(--red);
  flex-shrink: 0;
  margin-left: 20px;
}
.faq-item.active .faq-question .icon { transform: rotate(45deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}
.faq-item.active .faq-answer { max-height: 300px; }
.faq-answer p {
  color: var(--gray);
  line-height: 1.8;
  padding-bottom: 24px;
  font-size: 0.95rem;
}

/* DIGITAL FEATURES */
.features-section { background: var(--bg); }
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 30px;
}
.feature-card {
  background: var(--bg-card);
  border: 1px solid rgba(255, 255, 255, 0.06);
  padding: 40px 30px;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}
.feature-card::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0; right: 0;
  height: 3px;
  background: var(--red);
  transform: scaleX(0);
  transition: transform var(--transition);
}
.feature-card:hover::after { transform: scaleX(1); }
.feature-card:hover { border-color: rgba(255, 0, 0, 0.15); transform: translateY(-4px); }
.feature-card h3 {
  font-family: var(--font-heading);
  font-size: 1.2rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  margin-bottom: 12px;
  color: var(--red);
}
.feature-card p {
  color: var(--gray);
  line-height: 1.7;
  font-size: 0.93rem;
}

/* CTA BANNER */
.cta-banner {
  background: var(--bg-card);
  text-align: center;
  padding: 80px 0;
  border-top: 3px solid var(--red);
}

/* PAGE HERO (shorter) */
.page-hero {
  min-height: 45vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: linear-gradient(135deg, rgba(255, 0, 0, 0.1) 0%, var(--bg) 60%);
  position: relative;
}
.page-hero::before {
  content: '';
  position: absolute;
  bottom: 0; left: 0; right: 0;
  height: 100px;
  background: linear-gradient(to top, var(--bg-light), transparent);
  pointer-events: none;
}
.page-hero h1 {
  font-family: var(--font-heading);
  font-size: clamp(2.2rem, 5vw, 4rem);
  text-transform: uppercase;
  letter-spacing: 4px;
  font-weight: 700;
  line-height: 1.15;
}
.page-hero h1 span { color: var(--red); }
.page-hero p {
  color: var(--gray);
  font-size: 1.05rem;
  margin-top: 16px;
  max-width: 550px;
  margin-left: auto;
  margin-right: auto;
}

/* MOBILE NAV */
.mobile-nav {
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100vh;
  background: rgba(10, 10, 10, 0.98);
  z-index: 999;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 24px;
}
.mobile-nav.open { display: flex; }
.mobile-nav a {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  text-transform: uppercase;
  letter-spacing: 3px;
  color: var(--gray-light);
  transition: color var(--transition);
}
.mobile-nav a:hover { color: var(--red); }
.mobile-nav-close {
  position: absolute;
  top: 24px;
  right: 24px;
  background: none;
  color: var(--white);
  font-size: 2rem;
}

/* RESPONSIVE */
@media (max-width: 1024px) {
  .nav-links { display: none; }
  .nav-utility { display: none; }
  .hamburger { display: flex; }
}

@media (max-width: 768px) {
  section { padding: 70px 0; }
  .hero { min-height: 70vh; }
  .two-ways-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 30px; }
  .footer-bottom { flex-direction: column; gap: 12px; text-align: center; }
  .newsletter-form { flex-direction: column; }
  .newsletter-form button { padding: 16px; }
  .schedule-table th, .schedule-table td { padding: 14px 16px; }
  .filter-controls { gap: 8px; }
  .filter-btn { padding: 8px 16px; font-size: 0.7rem; }
  .features-grid { grid-template-columns: 1fr; }
}

@media (max-width: 480px) {
  .hero-btns { flex-direction: column; align-items: center; }
  .btn-primary, .btn-secondary { width: 100%; text-align: center; }
  .footer-grid { grid-template-columns: 1fr; }
  .page-hero { min-height: 35vh; }
}

